/// Runner → server.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all_fields = "camelCase")]
pub enum RunnerMessage {
    /// First message on every connection, so a server that missed messages catches up.
    #[serde(rename = "hello")]
    Hello {
        runner_id: String,
        hostname: String,
        os: String,
        arch: String,
        version: String,
        #[serde(default)]
        sessions: Vec<LiveSession>,
        /// Sessions that ended since the last connection, causes included.
        #[serde(default)]
        ended: Vec<SessionEnd>,
    },
    #[serde(rename = "health")]
    Health {
        health: Health,
    },
    #[serde(rename = "session.opened")]
    SessionOpened {
        session: SessionInfo,
    },
    #[serde(rename = "session.error")]
    SessionError {
        id: Uuid,
        message: String,
    },
    #[serde(rename = "session.ended")]
    SessionEnded {
        end: SessionEnd,
    },
    #[serde(rename = "session.activity")]
    SessionActivity {
        id: Uuid,
        activity: Activity,
    },
    /// The screen and scrollback asked for by `session.replay`, as bytes that repaint a fresh terminal.
    #[serde(rename = "session.replay")]
    SessionReplay {
        id: Uuid,
        nonce: String,
        /// Base64.
        data: String,
    },
    /// How a runner update is going: checking, installing, restarting, upToDate, failed, or newer (the feed has a newer release than the one asked for, so nothing was installed).
    #[serde(rename = "update.status")]
    UpdateStatus {
        state: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        version: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
    },
    /// How an `agent.login` is going.
    #[serde(rename = "agent.login_status")]
    AgentLoginStatus {
        status: AgentLoginStatus,
    },
    /// Plan usage readings that changed (all of them again on reconnect).
    #[serde(rename = "usage")]
    Usage {
        #[serde(default)]
        agents: Vec<AgentUsage>,
    },
    /// A session's latest spend reading (again on reconnect, and once more just before it ends).
    #[serde(rename = "session.cost")]
    SessionCost {
        cost: SessionCost,
    },
    /// A tool call from an agent in one of this runner's sessions (or `tools/list`, for its tools).
    #[serde(rename = "mcp.request")]
    McpRequest {
        req_id: String,
        session: Uuid,
        tool: String,
        args: serde_json::Value,
    },
    /// A task's worktree is made: where it came from.
    #[serde(rename = "task.started")]
    TaskStarted {
        task_id: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        repo: Option<String>,
        repo_dir: String,
        base: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        project: Option<String>,
    },
    #[serde(rename = "task.finished")]
    TaskFinished {
        task_id: String,
        ok: bool,
        /// app (a GitHub App token) or fallback (the machine's credentials).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pushed: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        owner: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        repo: Option<String>,
        branch: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        base: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        commit: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        reason: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
        /// The repo's checks that ran, in order; the last one failed when the finish stopped on a check (nothing committed or pushed).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        checks: Option<Vec<CheckRun>>,
    },
    /// What a task's branch changes against its base: line counts per file and the unified patch.
    #[serde(rename = "task.diff")]
    TaskDiff {
        task_id: String,
        ok: bool,
        #[serde(default)]
        files: Vec<DiffStat>,
        patch: String,
        truncated: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
        /// The branch's commits, oldest first; none from runners that predate it.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        commits: Option<Vec<DiffCommit>>,
    },
    #[serde(rename = "task.merged")]
    TaskMerged {
        task_id: String,
        ok: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        commit: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
        /// What became of the merged branch on origin: deleted, gone (already), moved (kept: it has commits that didn't merge) or `failed: <why>`.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        branch: Option<String>,
    },
    /// How a dry-run merge of a task's branch into its base went: `clean`, or the `conflicts` paths. Nothing was changed.
    #[serde(rename = "task.merge_check")]
    TaskMergeCheck {
        task_id: String,
        /// The check ran; false: `message` says why not.
        ok: bool,
        clean: bool,
        #[serde(default)]
        conflicts: Vec<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
    },
    /// How `task.handoff` went: the branch is on origin at `commit`, or `message` says why not.
    #[serde(rename = "task.handed_off")]
    TaskHandedOff {
        task_id: String,
        ok: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pushed: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        commit: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
    },
    /// What a draft's agent is doing (a `tool` line, the default) or saying (`text`).
    #[serde(rename = "draft.progress")]
    DraftProgress {
        id: String,
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        kind: Option<DraftLineKind>,
    },
    /// A draft's agent finished: its last message, or why it couldn't.
    #[serde(rename = "draft.done")]
    DraftDone {
        id: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        output: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        error: Option<String>,
    },
    /// A line about setting a task's worktree up or cleaning it up (a worktree script starting or finishing), for its timeline.
    #[serde(rename = "task.progress")]
    TaskProgress {
        task_id: String,
        text: String,
    },
    #[serde(rename = "task.cleaned")]
    TaskCleaned {
        task_id: String,
        ok: bool,
        branch_deleted: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        message: Option<String>,
    },
    /// A GitHub token to fetch or push a task's repo.
    #[serde(rename = "task.token_request")]
    TaskTokenRequest {
        req_id: String,
        task_id: String,
        owner: String,
        repo: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        purpose: Option<String>,
    },
    /// A repo's secrets: for a task assigned to this machine (`taskId`), or for its owner's own checkout (`maple-runner secrets pull`).
    #[serde(rename = "secrets.request")]
    SecretsRequest {
        req_id: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        task_id: Option<String>,
        /// GitHub owner/name.
        repo: String,
    },
}

/// Server → runner.
